local M = class("SmashEggsAwardInfoModel", LikeOO.OODataBase)

M.point = {}

function M:onCreate()
    self.m_version = self.m_params.version
    self:getData()
end

function M:getRewardsData()
    local tempData = {}
    local tempList = {}
    local wish_rewardData = ConfigManager:getCfgByName("egg")
    versionData = wish_rewardData[self.m_version] or {}
    for index, itemData in pairs(versionData) do
        tempList[index] = {
            awardData = itemData.reward[1],
            weight = itemData.show_weight or 0,
        }
    end
    return tempList
end

function M:onEnter()

end

return M